const input = $input.first().json;
const body = input.body || input;
const { whatsapp } = body;

if (!whatsapp) {
  throw new Error('Falta el campo requerido: whatsapp');
}

const wa = String(whatsapp).replace(/'/g, "''");
const query = `SELECT id, estado FROM alumnos WHERE whatsapp = '${wa}' LIMIT 1;`;

return [{ json: { query } }];

const webhookInput = $('When Executed by Another Workflow').first().json;
const body = webhookInput.body || webhookInput;
const {
  monto,
  tipo_pago,
  canal,
  moneda,
  periodo,
  estado_pago,
  comprobante_url,
  comprobante_monto,
  horario_id
} = body;

const alumnoRows = $input.all().map(i => i.json).filter(j => j && j.id);
if (alumnoRows.length === 0) {
  throw new Error('No existe un alumno pre-registrado con ese whatsapp. No se puede registrar el pago hasta que haya elegido un horario y quede pre-registrado (ver tool convertir-lead-a-alumno).');
}
const alumno = alumnoRows[0];

if (!monto) {
  throw new Error('Falta el campo requerido: monto');
}
if (!comprobante_url) {
  throw new Error('Falta el campo requerido: comprobante_url (link del comprobante ya guardado en Drive)');
}

const montoNum = parseFloat(monto);
const compMontoNum = comprobante_monto ? parseFloat(comprobante_monto) : montoNum;
const tipo = tipo_pago ? String(tipo_pago).replace(/'/g, "''") : 'mensualidad';
const can = canal ? String(canal).replace(/'/g, "''") : 'whatsapp_comprobante';
const mon = moneda ? String(moneda).replace(/'/g, "''") : 'ARS';
const per = periodo ? String(periodo).replace(/'/g, "''") : new Date().toISOString().slice(0, 7);
const est = estado_pago ? String(estado_pago).replace(/'/g, "''") : 'PENDIENTE_VERIFICACION';
const compUrl = String(comprobante_url).replace(/'/g, "''");
const horId = horario_id ? parseInt(horario_id) : null;

const query = `INSERT INTO pagos (alumno_id, horario_id, tipo, canal, monto, moneda, periodo, estado, comprobante_url, comprobante_fecha, comprobante_monto, created_at, updated_at)
VALUES (${alumno.id}, ${horId !== null ? horId : 'null'}, '${tipo}', '${can}', ${montoNum}, '${mon}', '${per}', '${est}', '${compUrl}', CURRENT_DATE, ${compMontoNum}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
RETURNING id, alumno_id, monto, estado, comprobante_url, periodo, created_at;`;

return [{ json: { query, alumno_estado_actual: alumno.estado } }];

const result = $input.first().json;
const extra = $('Build Query Insertar Pago').first().json;

return [{
  json: {
    success: true,
    message: 'Comprobante registrado, pendiente de verificación por Fla',
    pago: {
      id: result.id,
      alumno_id: result.alumno_id,
      monto: result.monto,
      estado: result.estado,
      comprobante_url: result.comprobante_url,
      periodo: result.periodo,
      created_at: result.created_at
    },
    alumno_estado_actual: extra.alumno_estado_actual
  }
}];
